import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as e,e as n}from"./app-4490560f.js";const t={},i=n(`<h1 id="gnupg-gpg-加密签名工具-pgp-实现" tabindex="-1"><a class="header-anchor" href="#gnupg-gpg-加密签名工具-pgp-实现" aria-hidden="true">#</a> gnupg（GPG 加密签名工具（PGP 实现））</h1><blockquote><p>Homebrew 版本 2.4.8 ｜ 主页：见官方文档 ｜ 安装：<code>brew install gnupg</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>GnuPG（GNU Privacy Guard，简称 GPG）是 PGP（Pretty Good Privacy）加密标准的自由开源实现，用于数据加密、数字签名以及身份认证。它解决的核心问题是如何在公开网络上安全地传输数据、验证文件来源的真实性和完整性——典型场景包括：用公钥加密文件后发送给他人、对发布包或 Git 提交做数字签名、以及用密钥对加密和解密口令/备份。其加密算法基于现代非对称加密（如 RSA、ECC），安全性经过了全球广泛验证。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> gnupg

<span class="token comment"># 升级（先更新 brew 索引）</span>
brew update
brew upgrade gnupg

<span class="token comment"># 卸载</span>
brew uninstall gnupg

<span class="token comment"># 验证安装成功（应输出类似 gpg (GnuPG) 2.4.8）</span>
gpg <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>gpg --full-generate-key</code></td><td>交互式生成新密钥对（推荐用 <code>--full-*</code> 以便自定义算法）</td><td><code>gpg --full-generate-key</code></td></tr><tr><td><code>gpg --list-keys</code></td><td>列出本地所有公钥</td><td><code>gpg --list-keys</code></td></tr><tr><td><code>gpg --list-secret-keys</code></td><td>列出本地所有私钥</td><td><code>gpg --list-secret-keys</code></td></tr><tr><td><code>gpg --export</code></td><td>导出公钥（ASCII 格式用 <code>--armor</code>）</td><td><code>gpg --armor --export alice@example.com</code></td></tr><tr><td><code>gpg --import</code></td><td>导入他人公钥</td><td><code>gpg --import bob.pub.asc</code></td></tr><tr><td><code>gpg -e</code> / <code>--encrypt</code></td><td>加密文件（配合 <code>-r</code> 指定收件人公钥）</td><td><code>gpg -e -r bob@example.com secret.txt</code></td></tr><tr><td><code>gpg -d</code> / <code>--decrypt</code></td><td>解密文件</td><td><code>gpg -d secret.txt.gpg</code></td></tr><tr><td><code>gpg -s</code> / <code>--sign</code></td><td>对文件做签名（默认二进制签名）</td><td><code>gpg -s release.tar.gz</code></td></tr><tr><td><code>gpg --verify</code></td><td>验证签名</td><td><code>gpg --verify release.tar.gz.sig release.tar.gz</code></td></tr><tr><td><code>gpg --delete-secret-keys</code></td><td>删除私钥（删除公钥用 <code>--delete-keys</code>）</td><td><code>gpg --delete-secret-keys KEYID</code></td></tr><tr><td><code>gpg --export-secret-keys</code></td><td>备份私钥（务必加 <code>--armor</code> 并妥善保管）</td><td><code>gpg --armor --export-secret-keys KEYID &gt; backup.asc</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-生成密钥对" tabindex="-1"><a class="header-anchor" href="#示例-1-生成密钥对" aria-hidden="true">#</a> 示例 1：生成密钥对</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 交互式生成，按提示选择密钥类型与用途，设置口令（passphrase）</span>
gpg --full-generate-key

<span class="token comment"># 查看生成的密钥</span>
gpg --list-keys

<span class="token comment"># 输出示例（KEYID 是第二行十六进制指纹的后 16 位）</span>
<span class="token comment"># pub   rsa3072 2026-01-01 [SC] [有效至: 2028-01-01]</span>
<span class="token comment">#       ABCDEF0123456789ABCDEF0123456789ABCDEF01</span>
<span class="token comment"># uid           [ 终极 ] Alice &lt;alice@example.com&gt;</span>
<span class="token comment"># sub   rsa3072 2026-01-01 [E] [有效至: 2028-01-01]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-加密与解密文件" tabindex="-1"><a class="header-anchor" href="#示例-2-加密与解密文件" aria-hidden="true">#</a> 示例 2：加密与解密文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 导出自己的公钥发给对方（或导入对方的公钥）</span>
gpg <span class="token parameter variable">--armor</span> <span class="token parameter variable">--export</span> alice@example.com <span class="token operator">&gt;</span> alice.pub.asc

<span class="token comment"># 2. 导入对方（Bob）的公钥</span>
gpg <span class="token parameter variable">--import</span> bob.pub.asc

<span class="token comment"># 3. 用 Bob 的公钥加密文件（只有 Bob 的私钥能解密）</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;绝密内容&quot;</span> <span class="token operator">&gt;</span> secret.txt
gpg <span class="token parameter variable">-e</span> <span class="token parameter variable">-r</span> bob@example.com secret.txt
<span class="token comment"># 生成 secret.txt.gpg</span>

<span class="token comment"># 4. Bob 解密</span>
gpg <span class="token parameter variable">-d</span> secret.txt.gpg
<span class="token comment"># 输出原始内容到屏幕；如需写回文件用 --output</span>
gpg <span class="token parameter variable">-d</span> secret.txt.gpg <span class="token parameter variable">--output</span> secret.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-签名并校验文件完整性" tabindex="-1"><a class="header-anchor" href="#示例-3-签名并校验文件完整性" aria-hidden="true">#</a> 示例 3：签名并校验文件完整性</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 对发布包做二进制签名</span>
gpg <span class="token parameter variable">-s</span> release-2.4.8.tar.gz
<span class="token comment"># 生成 release-2.4.8.tar.gz.gpg（内含原文+签名）</span>

<span class="token comment"># 2. 单独分离签名（--detach-sign），不修改原文件</span>
gpg --detach-sign <span class="token parameter variable">--armor</span> release-2.4.8.tar.gz
<span class="token comment"># 生成 release-2.4.8.tar.gz.asc</span>

<span class="token comment"># 3. 校验签名</span>
gpg <span class="token parameter variable">--verify</span> release-2.4.8.tar.gz.asc release-2.4.8.tar.gz
<span class="token comment"># 输出 gpg: 好的签名 以及签名者身份，说明文件未被篡改</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>为 Git 提交签名</strong>：GPG 与 Git 搭配是最常见的场景。生成密钥后执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> config <span class="token parameter variable">--global</span> user.signingkey KEYID
<span class="token function">git</span> config <span class="token parameter variable">--global</span> commit.gpgsign <span class="token boolean">true</span>   <span class="token comment"># 之后所有提交自动签名</span>
<span class="token function">git</span> commit <span class="token parameter variable">-S</span> <span class="token parameter variable">-m</span> <span class="token string">&quot;签名提交&quot;</span>              <span class="token comment"># 或临时用 -S 强制签名</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在 GitHub/GitLab 的 SSH 或 GPG 设置里粘贴 <code>gpg --armor --export KEYID</code> 的输出来绑定身份。</p></li><li><p><strong>配置文件位置</strong>：用户级配置在 <code>~/.gnupg/</code>，常用文件为 <code>~/.gnupg/gpg.conf</code>（命令行默认参数）、<code>~/.gnupg/dirmngr.conf</code>（密钥服务器网络）。可在 <code>gpg.conf</code> 里持久化常用选项，例如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ~/.gnupg/gpg.conf</span>
default-key KEYID
keyserver hkps://keys.openpgp.org
auto-key-retrieve
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>明文输出与二进制混合</strong>：加密时若希望可读/可传输到邮件，加 <code>--armor</code> 生成 ASCII 装甲格式（<code>.asc</code>）；不加则默认二进制。命令行参数优先级高于配置文件。</p></li><li><p><strong>环境变量</strong>：GPG 常用 <code>GNUPGHOME</code> 指定密钥目录（默认 <code>~/.gnupg</code>），便于多密钥集隔离或用于 CI：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">GNUPGHOME</span><span class="token operator">=</span>/path/to/my/gpg-home
gpg --list-keys
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>子密钥（Subkey）管理</strong>：推荐&quot;主密钥离线保管 + 子密钥日常使用&quot;。生成时默认自动生成一个签名子钥与加密子钥；加密/签名操作实际使用的是子密钥，主密钥只用于签发/吊销子密钥。日常导出用子密钥，主密钥备份单独封存：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>gpg --list-secret-keys --with-subkey-fingerprint KEYID
<span class="token comment"># 备份仅私钥子钥（不含主密钥），适合放入 YubiKey 等智能卡</span>
gpg --export-secret-subkeys KEYID<span class="token operator">!</span> <span class="token operator">&gt;</span> subkey-backup.asc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>批量生成密钥（非交互）</strong>：用 <code>--batch</code> + 参数文件可无人值守生成，适合脚本与 CI：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># keygen-input 文件内容见下方&quot;批量生成参数模板&quot;</span>
gpg <span class="token parameter variable">--batch</span> --generate-key keygen-input
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>参数模板示例（<code>keygen-input</code>）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>%no-protection
Key-Type: eddsa
Key-Curve: ed25519
Key-Usage: sign
Subkey-Type: ecdh
Subkey-Curve: cv25519
Subkey-Usage: encrypt
Name-Real: CI Bot
Name-Email: ci@example.com
Expire-Date: 1y
%commit
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>智能卡 / YubiKey</strong>：GnuPG 支持 OpenPGP 智能卡，配合 <code>gpg-agent</code> 与 <code>scdaemon</code> 将私钥安全存放在硬件上。插入卡片后验证：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>gpg --card-status          <span class="token comment"># 查看卡片信息与公钥</span>
gpg --card-edit            <span class="token comment"># 交互式设置 PIN、管理密钥槽</span>
gpg --edit-key KEYID        <span class="token comment"># 用 keytocard 命令把子密钥转移到卡上</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>对称加密（无公钥）</strong>：只有口令、不需密钥对时用 <code>-c</code>，适合个人备份或临时分享：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>gpg <span class="token parameter variable">-c</span> secret.txt               <span class="token comment"># 提示输入口令，生成 secret.txt.gpg</span>
gpg <span class="token parameter variable">-c</span> --cipher-algo AES256 <span class="token parameter variable">-o</span> secret.asc secret.txt   <span class="token comment"># 指定算法并装甲</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>输出重定向与内存安全</strong>：所有明文文件操作建议显式加 <code>--output</code> 而非隐式改名，避免误覆盖。解密时若不加 <code>--output</code> 会直接打印到 stdout，请勿重定向到终端以外的危险命令；涉及敏感内容可配合 <code>--no-symkey-cache</code> 禁用对称密钥缓存。</p></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ul><li><strong>私钥绝不外泄</strong>：<code>--export-secret-keys</code> 导出的私钥一旦泄露，任何人可冒充你签名、解密你的数据。备份私钥文件时应加密存储，且不同平台分开保管。吊销证书（<code>gpg --gen-revoke KEYID</code>）应在生成密钥时就生成并妥善保存。</li><li><strong>口令（passphrase）遗忘无法找回</strong>：GPG 私钥加密后没有找回机制，忘记口令即永久失去该私钥，请务必使用密码管理器保存。</li><li><strong>公钥信任与认证</strong>：仅导入公钥不等于信任其身份，建议通过 <code>gpg --edit-key KEYID</code> 进入交互模式用 <code>trust</code> 命令设置信任级别，防止中间人攻击。</li><li><strong>常见报错 <code>no valid OpenPGP data found</code></strong>：通常因解密/校验对象不是 GPG 数据（如未加密的普通文件），或导入的是一段被截断的 ASCII 内容——检查文件类型并确保命令与对象匹配。</li><li><strong>性能与安全</strong>：非对称加密（RSA/ECC）较慢，加密大文件时建议先压缩（如 <code>tar czf</code>）再加密；或先用对称加密（<code>gpg -c</code>）再用公钥加密会话密钥。生成密钥时选择 3072 位 RSA 或 256 位 ECC（如 <code>ed25519</code>）为目前推荐强度。</li></ul><h3 id="新手踩坑" tabindex="-1"><a class="header-anchor" href="#新手踩坑" aria-hidden="true">#</a> 新手踩坑</h3><ul><li><strong>改了密钥目录却不生效</strong>：设置 <code>GNUPGHOME</code> 后若与旧目录一致，可用 <code>--homedir</code> 临时指定并确认 <code>gpg --list-keys</code> 有内容；多密钥集务必确认当前 <code>GNUPGHOME</code> 指向正确。</li><li><strong>Git 提交报 <code>gpg: skipped ... no secret key</code></strong>：通常是 <code>user.signingkey</code> 填成了公钥指纹而非私钥 ID，或 <code>GPG_TTY</code> 未导出导致无法弹出口令窗口。在 shell 配置（<code>~/.zshrc</code>/<code>~/.bashrc</code>）里加入：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">GPG_TTY</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">tty</span><span class="token variable">)</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><strong><code>gpg: keyserver receive failed: No name</code></strong>：多为 keyserver 域名拼写错误或网络被墙；改用国内可达的 keyserver 或 hkps 端口。</li><li><strong><code>Inappropriate ioctl for device</code>（macOS 弹窗问题）</strong>：同上，多数因 <code>GPG_TTY</code> 未设置；或在 <code>~/.gnupg/gpg-agent.conf</code> 加 <code>pinentry-program</code> 指向图形 pinentry。</li><li><strong>导入别人密钥后加密仍报找不到密钥</strong>：确认用 <code>gpg --list-keys</code> 能看到对方 UID；多公钥同邮箱时用完整指纹或 <code>!</code> 后缀精确指定收件人，如 <code>-r 0xABC...!</code>。</li><li><strong>吊销证书（revocation cert）务必离线保存</strong>：它不加密私钥，任何人都可用它吊销你的公钥。生成后立即存到安全介质（U 盘/U 盾），不要和私钥放一起，也不要放在已导出的 <code>.asc</code> 备份里。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-加密压缩包并自动命名" tabindex="-1"><a class="header-anchor" href="#_1-加密压缩包并自动命名" aria-hidden="true">#</a> 1. 加密压缩包并自动命名</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先用 tar 压缩再用公钥加密（对称加密会先压缩，公钥加密不会）</span>
<span class="token function">tar</span> czf backup.tar.gz ./important/
gpg <span class="token parameter variable">-e</span> <span class="token parameter variable">-r</span> alice@example.com <span class="token parameter variable">-o</span> backup.tar.gz.gpg backup.tar.gz
<span class="token function">rm</span> backup.tar.gz   <span class="token comment"># 安全删除明文压缩包</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-与-find-批量加密-解密" tabindex="-1"><a class="header-anchor" href="#_2-与-find-批量加密-解密" aria-hidden="true">#</a> 2. 与 find 批量加密/解密</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 批量加密某个目录下所有 .txt 文件（保留原文件）</span>
<span class="token function">find</span> ./docs <span class="token parameter variable">-name</span> <span class="token string">&#39;*.txt&#39;</span> <span class="token parameter variable">-exec</span> gpg <span class="token parameter variable">-e</span> <span class="token parameter variable">-r</span> alice@example.com <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">\\</span><span class="token punctuation">;</span>
<span class="token comment"># 批量解密所有 .gpg 文件到原始名</span>
<span class="token function">find</span> ./docs <span class="token parameter variable">-name</span> <span class="token string">&#39;*.gpg&#39;</span> <span class="token parameter variable">-exec</span> <span class="token function">sh</span> <span class="token parameter variable">-c</span> <span class="token string">&#39;gpg -d &quot;$1&quot; -o &quot;\${1%.gpg}&quot;&#39;</span> _ <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">\\</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-与-rsync-scp-网络传输搭配" tabindex="-1"><a class="header-anchor" href="#_3-与-rsync-scp-网络传输搭配" aria-hidden="true">#</a> 3. 与 rsync/scp/网络传输搭配</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 边加密边传输到远端，避免明文落盘</span>
<span class="token function">tar</span> czf - ./confidential <span class="token operator">|</span> gpg <span class="token parameter variable">-e</span> <span class="token parameter variable">-r</span> alice@example.com <span class="token operator">|</span> <span class="token function">ssh</span> server <span class="token string">&#39;cat &gt; /remote/confidential.gpg&#39;</span>
<span class="token comment"># 远端解密</span>
<span class="token function">ssh</span> server <span class="token string">&#39;gpg -d /remote/confidential.gpg&#39;</span> <span class="token operator">|</span> <span class="token function">tar</span> xzf -
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-makefile-自动化签名发布包" tabindex="-1"><a class="header-anchor" href="#_4-makefile-自动化签名发布包" aria-hidden="true">#</a> 4. Makefile 自动化签名发布包</h3><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile —— 发布前自动签名并校验</span>
VERSION <span class="token operator">:=</span> 2.4.8
KEYID   <span class="token operator">:=</span> YOUR_KEYID
PKG     <span class="token operator">:=</span> release-<span class="token variable">$</span><span class="token punctuation">(</span>VERSION<span class="token punctuation">)</span>.tar.gz

<span class="token target symbol">dist</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>
	<span class="token operator">@</span>echo <span class="token string">&quot;=== 签名发布包 ===&quot;</span>
	gpg --detach-sign --armor -u <span class="token variable">$</span><span class="token punctuation">(</span>KEYID<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>
	<span class="token operator">@</span>echo <span class="token string">&quot;=== 校验签名 ===&quot;</span>
	gpg --verify <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>.asc <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>

<span class="token target symbol">verify</span><span class="token punctuation">:</span>
	gpg --verify <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>.asc <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -f <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>PKG<span class="token punctuation">)</span>.asc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-github-actions-中解密机密" tabindex="-1"><a class="header-anchor" href="#_5-github-actions-中解密机密" aria-hidden="true">#</a> 5. GitHub Actions 中解密机密</h3><p>CI 中常用&quot;加密的机密文件&quot;来安全传递密钥。先在本地用对称加密，再在 Actions 里解密：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 本地：用口令加密 secrets.env（GPG 走非交互读环境变量 GPG_PASS）</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;API_TOKEN=xxx&quot;</span> <span class="token operator">|</span> gpg <span class="token parameter variable">-c</span> --cipher-algo AES256 <span class="token parameter variable">-o</span> secrets.env.gpg
<span class="token comment"># 把 secrets.env.gpg 提交入库，把口令放进 GitHub Secrets 名为 GPG_PASS</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/release.yml（片段）</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 解密机密
  <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
    echo &quot;\${{ secrets.GPG_PASS }}&quot; | gpg --batch --yes --passphrase-fd 0 \\
      -d secrets.env.gpg -o secrets.env</span>
  <span class="token comment"># 随后 source secrets.env 或读取所需变量</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：更推荐的做法是使用专用的&quot;GPG 私钥&quot;作为 Secret，配合 <code>crazy-max/ghaction-import-gpg</code> 在 Actions 里导入用于签名发布产物。将私钥 base64 后存入 GitHub Secrets，再加 passphrase Secret：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> crazy<span class="token punctuation">-</span>max/ghaction<span class="token punctuation">-</span>import<span class="token punctuation">-</span>gpg@v6
  <span class="token key atrule">with</span><span class="token punctuation">:</span>
    <span class="token key atrule">gpg_private_key</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GPG_PRIVATE_KEY <span class="token punctuation">}</span><span class="token punctuation">}</span>
    <span class="token key atrule">passphrase</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GPG_PASSPHRASE <span class="token punctuation">}</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></blockquote><h3 id="_6-与密码管理器-备份脚本结合" tabindex="-1"><a class="header-anchor" href="#_6-与密码管理器-备份脚本结合" aria-hidden="true">#</a> 6. 与密码管理器/备份脚本结合</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># backup.sh —— 每日加密备份</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail
<span class="token assign-left variable">TS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%F<span class="token variable">)</span></span>
<span class="token function">tar</span> czf <span class="token string">&quot;/tmp/bak-<span class="token variable">$TS</span>.tar.gz&quot;</span> ~/Documents ~/Pictures
gpg <span class="token parameter variable">-e</span> <span class="token parameter variable">-r</span> alice@example.com <span class="token parameter variable">-o</span> <span class="token string">&quot;<span class="token environment constant">$HOME</span>/backups/bak-<span class="token variable">$TS</span>.tar.gz.gpg&quot;</span> <span class="token string">&quot;/tmp/bak-<span class="token variable">$TS</span>.tar.gz&quot;</span>
<span class="token function">rm</span> <span class="token string">&quot;/tmp/bak-<span class="token variable">$TS</span>.tar.gz&quot;</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;已备份到 <span class="token environment constant">$HOME</span>/backups/bak-<span class="token variable">$TS</span>.tar.gz.gpg&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-用脚本校验上游发布包-供应链安全" tabindex="-1"><a class="header-anchor" href="#_7-用脚本校验上游发布包-供应链安全" aria-hidden="true">#</a> 7. 用脚本校验上游发布包（供应链安全）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 下载软件及其签名与公钥，校验后安装</span>
<span class="token function">curl</span> <span class="token parameter variable">-fsSL</span> <span class="token parameter variable">-O</span> https://example.com/app.tar.gz
<span class="token function">curl</span> <span class="token parameter variable">-fsSL</span> <span class="token parameter variable">-O</span> https://example.com/app.tar.gz.asc
gpg <span class="token parameter variable">--keyserver</span> hkps://keys.openpgp.org --recv-keys 0xABC<span class="token punctuation">..</span>.   <span class="token comment"># 获取开发者公钥</span>
gpg <span class="token parameter variable">--verify</span> app.tar.gz.asc app.tar.gz <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;签名有效，可安全安装&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,39),c=[i];function l(p,r){return s(),e("div",null,c)}const u=a(t,[["render",l],["__file","gnupg.html.vue"]]);export{u as default};
